#!/usr/bin/env python3
"""Final verification with fixed ping detection."""
import json, re
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def ping_ok(output):
    """Check if ping succeeded by looking for received > 0."""
    m = re.search(r'(\d+)\s+(?:packets\s+)?received', output)
    if m and int(m.group(1)) > 0:
        return True
    m = re.search(r'(\d+) packets transmitted, (\d+) received', output)
    if m and int(m.group(2)) > 0:
        return True
    return False

non_guest = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
}
guest = {
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}
all_hosts = {**non_guest, **guest}
non_guest_addrs = [v[1] for v in non_guest.values()]
guest_addrs = [v[1] for v in guest.values()]
internet = ["8.8.8.8", "1.1.1.1"]

def ping_from_host(name, mgmt_ip, targets):
    results = {}
    conn = ConnectHandler(device_type="linux", host=mgmt_ip, username="root", password="alpine", timeout=30)
    for t in targets:
        try:
            out = conn.send_command(f"ping -c 2 -W 3 {t}", read_timeout=15)
            results[t] = ping_ok(out)
        except Exception as e:
            results[t] = False
    conn.disconnect()
    return name, results

ping_results = {}
with ThreadPoolExecutor(max_workers=10) as pool:
    futures = []
    for name, (mgmt, lab) in non_guest.items():
        targets = [a for a in non_guest_addrs if a != lab] + internet + guest_addrs
        futures.append(pool.submit(ping_from_host, name, mgmt, targets))
    for name, (mgmt, lab) in guest.items():
        targets = [a for a in guest_addrs if a != lab] + internet + non_guest_addrs
        futures.append(pool.submit(ping_from_host, name, mgmt, targets))
    for f in as_completed(futures):
        name, results = f.result()
        ping_results[name] = results

# Non-guest to non-guest
print("=== Non-guest to non-guest (should PASS) ===")
ng_pass = ng_fail = 0
for src in sorted(non_guest):
    for dst in sorted(non_guest):
        if src == dst: continue
        ok = ping_results[src].get(non_guest[dst][1], False)
        if ok: ng_pass += 1
        else:
            ng_fail += 1
            print(f"  FAIL: {src} -> {dst}")
print(f"  Total: {ng_pass} pass, {ng_fail} fail")

# Guest to guest
print("\n=== Guest to guest (should PASS) ===")
for src in sorted(guest):
    for dst in sorted(guest):
        if src == dst: continue
        ok = ping_results[src].get(guest[dst][1], False)
        print(f"  {src} -> {dst}: {'PASS' if ok else 'FAIL'}")

# Guest <-> non-guest (should FAIL)
print("\n=== Guest -> non-guest (should FAIL) ===")
gp = gf = 0
for src in sorted(guest):
    for dst in sorted(non_guest):
        ok = ping_results[src].get(non_guest[dst][1], False)
        if not ok: gp += 1
        else:
            gf += 1
            print(f"  WRONG PASS: {src} -> {dst}")
print(f"  Correctly blocked: {gp}, incorrectly passed: {gf}")

print("\n=== Non-guest -> guest (should FAIL) ===")
np = nf = 0
for src in sorted(non_guest):
    for dst in sorted(guest):
        ok = ping_results[src].get(guest[dst][1], False)
        if not ok: np += 1
        else:
            nf += 1
            print(f"  WRONG PASS: {src} -> {dst}")
print(f"  Correctly blocked: {np}, incorrectly passed: {nf}")

# Internet
print("\n=== Internet pings (should PASS) ===")
ip = ifail = 0
for name in sorted(all_hosts):
    for t in internet:
        ok = ping_results[name].get(t, False)
        if ok: ip += 1
        else:
            ifail += 1
            print(f"  FAIL: {name} -> {t}")
print(f"  Total: {ip} pass, {ifail} fail")

